/* ======================================================================
   FAULT 12 - the Soviet surface fleet fired one weapon under six names
   ======================================================================
   eras.js generates naval armament from a per-ROLE template. Measured
   across all eight navies and all five generated eras, the only field that
   varies inside a role is `name`: every corvette in the game shares one
   projectile block, every destroyer another, every carrier a third. The
   TARGET MASK never follows the name, and on the Soviet roster that left
   six weapons doing the opposite of the thing they are called.

     w_e60_pact_carrier   "14 x Ka-25 ASW helicopters"  sub:0  air:1
     w_e90_pact_carrier   "12 x P-700 Granit"           sea:0  air:1
     w_e00_pact_carrier   "P-700 Granit"                sea:0  air:1
     w_e60_pact_corvette  "2 x RBU-6000"                sub:0  air:1
     w_e90_pact_corvette  "RBU-6000"                    sub:0  air:1
     w_e60_pact_destroyer "2 x M-1 Volna SAM"           air:0

   Moskva and Leningrad existed for one job - hunting Polaris boats in the
   Eastern Mediterranean - and their fourteen Ka-25PL could not attack a
   submarine. The P-700 Granit is a seven-tonne Mach-2.5 missile built to
   kill an American carrier, and on Kuznetsov it could shoot down aircraft
   and could not touch a ship. The RBU-6000 is a 213 mm mortar throwing
   depth bombs; rules.js already holds the correct entry for it, `asw_rbu`,
   tgt sub-only, five thousand lines away. And the Project 61 Kashin's whole
   reason to exist is the M-1 Volna, the first Soviet naval area missile,
   which here could not engage an aeroplane.

   THE SECOND HALF OF THE SAME FAULT is the mask that is too generous. Every
   Soviet anti-ship missile in the generated rosters carries ground:1, so the
   fleet can bombard a shore target with P-15 Termit, P-120 Malakhit, P-500
   Bazalt, P-700 Granit and P-1000 Vulkan. Not one of those has a land-attack
   role. They are carrier-killers with 500-750 kg warheads, active radar
   seekers and no terrain reference of any kind; the Soviet Navy's answer to
   a target ashore was naval gunfire, and after 1990 it was nothing at all
   until Kalibr. Granting the whole fleet a land-attack capability it never
   had, while the one missile that really does it - the 3M-14 Kalibr, fired
   from the Caspian Flotilla into Syria on 7 October 2015 - appears nowhere
   in the game as a weapon, is the wrong answer twice over.

   THE THIRD is area air defence, which after 1980 is the single largest
   difference between one surface combatant and another, and which the
   generated rosters do not model at all: not one Soviet hull from 1950 to
   2010 carries a weapon with an air-only mask. The S-300F Fort on a Slava
   or a Kirov - 64 and 96 rounds in below-deck revolver launchers, the one
   Soviet system in the Aegis conversation - simply is not in the game under
   any name, in any era. warship_specs.js already knows it is there: the
   Slava row carries vls:64 and Pyotr Velikiy vls:96, which are exactly those
   magazines. The armament table never got the message.

   Everything below runs BEFORE the domain pass on purpose, so the naval
   quality multiplier and privateWeapon() see the corrected fleet. Ranges
   are on the compressed naval tile scale the rest of the fleet uses (SM-2 at
   150 km is 14.5 tiles, Shtil at 50 km is 11.0), NOT R(metres), and the
   figures are authored at NATO-equivalent quality because DOMAIN.pact.naval
   = 0.72 is what is supposed to say the rest. New ids sit outside the
   w_<era>_<fac>_<role> pattern so no later normaliser rewrites them.       */

/* Appended, never prepended. giveWeapon() unshifts, which would put a SAM
   at weapons[0]; the build card reads that slot as the ship's main battery
   and combat.js's fallback scan walks forward from it. */
function addNaval(unitId, wid) {
  var u = UNITS[unitId];
  if (!u || !WEAPONS[wid]) return 0;
  u.weapons = (u.weapons || []).slice();
  if (u.weapons.indexOf(wid) < 0) u.weapons.push(wid);
  return 1;
}
function seaOnly(wid, nm) {
  var w = WEAPONS[wid]; if (!w) return 0;
  w.tgt = { ground: 0, air: 0, sea: 1, sub: 0 };
  if (nm) w.name = nm;
  return 1;
}

Object.assign(WEAPONS, {
  /* ---- Soviet naval area air defence, by generation ----
     M-1 Volna, 1962: the V-600, a navalised S-125 with 16 rounds on one
     twin ZIF-101 launcher. 15 km, beam-riding, one target at a time. It is
     not a good system by 1980 but in 1962 it is the reason the Kashin and
     the Kynda exist as escorts at all. */
  sam_volna_p: { name:"M-1 Volna (SA-N-1)", dmg:105, warhead:"flak", range:8.2,
    reload:6.4, burst:1, acc:0.58, proj:"missile", speed:500, profile:"pop", intercept:0.90,
    tgt:{ground:0,air:1,sea:0,sub:0}, sfx:"missile" },
  /* M-11 Shtorm, 1967: twin B-187 launchers, 48 rounds, 30 km. Moskva,
     Kresta II, Kara and Kiev. Bigger and longer-legged than Volna and still
     single-channel. */
  sam_shtorm_p: { name:"M-11 Shtorm (SA-N-3)", dmg:135, warhead:"flak", range:9.6,
    reload:5.8, burst:1, acc:0.62, proj:"missile", speed:520, profile:"pop", intercept:0.88,
    tgt:{ground:0,air:1,sea:0,sub:0}, sfx:"missile" },
  /* M-22 Uragan, 1980: the naval 9M38, the Buk at sea. Sovremenny's system,
     two single launchers, 48 rounds, 25 km. The later 9M317 is `sam_shtil`
     in rules.js and belongs to the 2000s export ships, not to a 1980 hull. */
  sam_uragan_p: { name:"M-22 Uragan (SA-N-7)", dmg:150, warhead:"flak", range:9.8,
    reload:5.2, burst:1, acc:0.66, proj:"missile", speed:540, profile:"pop", intercept:0.85,
    tgt:{ground:0,air:1,sea:0,sub:0}, sfx:"missile" },
  /* S-300F Fort, 1982 - THE fleet-defence system, and the single most
     important fact about a Slava or a Kirov as a warship. Eight below-deck
     revolver launchers, 64 rounds on Slava and 96 on a Kirov, 5V55RM out to
     75 km and the 48N6 of Fort-M on Pyotr Velikiy to 150. Multi-channel off
     a Tomb Stone phased array. This is the distinction between a fleet
     air-defence ship and a point-defence escort, and until now the game did
     not have it on the Soviet side at all. Deliberately short of sam_sm2
     (14.5): the system is real, the sensor and the datalink behind it are a
     generation behind Aegis, and DOMAIN.pact.naval says the rest. */
  sam_fort_p: { name:"S-300F Fort (SA-N-6)", dmg:185, warhead:"flak", range:12.6,
    reload:3.6, burst:2, burstDelay:0.4, acc:0.80, proj:"missile", speed:620, profile:"pop", intercept:0.62,
    tgt:{ground:0,air:1,sea:0,sub:0}, sfx:"missile" },
  /* 3K95 Kinzhal, 1991 - Kuznetsov's own system and NOT Shtil: 192 rounds of
     9M330 in 24 eight-cell revolvers, 12 km. A point/short-area weapon on a
     ship whose real air defence is supposed to be her air wing. */
  sam_kinzhal_p: { name:"3K95 Kinzhal (SA-N-9)", dmg:120, warhead:"flak", range:7.2,
    reload:3.0, burst:2, burstDelay:0.3, acc:0.72, proj:"missile", speed:580, profile:"pop", intercept:0.75,
    tgt:{ground:0,air:1,sea:0,sub:0}, sfx:"missile" },

  /* ---- the carrier-killers, anti-ship and nothing else ----
     750 kg warhead, Mach 2.5, salvo logic that lets one missile climb and
     spot for the rest. No terrain-following, no mission planning, no land
     attack in any variant. Twenty on a Kirov, twelve under Kuznetsov's
     flight deck, twenty-four in an Oscar. */
  ssm_granit_p: { name:"P-700 Granit (SS-N-19)", dmg:420, warhead:"he", range:15.5,
    minRange:2.5, reload:21.0, burst:1, acc:0.72, proj:"missile", speed:340, aoe:1.9, profile:"loft", intercept:0.42,
    tgt:{ground:0,air:0,sea:1,sub:0}, sfx:"missile" },
  /* P-1000 Vulkan, 1987: the P-500 Bazalt re-engined and given a lighter
     warhead for range. Sixteen in the fixed deck tubes of a Slava, no reload
     at sea - fire them and the ship is a gun platform, which is what the
     e20 unit description already says. */
  ssm_vulkan_p: { name:"P-1000 Vulkan (SS-N-12)", dmg:365, warhead:"he", range:14.6,
    minRange:2.5, reload:22.0, burst:1, acc:0.70, proj:"missile", speed:330, aoe:1.8, profile:"loft", intercept:0.48,
    tgt:{ground:0,air:0,sea:1,sub:0}, sfx:"missile" },
  /* P-270 Moskit, 1984 - NATO 'Sunburn'. Sea-skimming at Mach 2.2 with a
     terminal weave, and the reason a Sovremenny was built: eight rounds in
     two quad mounts, aimed at an amphibious group's escorts. Short-legged
     at 120 km because it flies the whole way low. */
  ssm_moskit_p: { name:"P-270 Moskit (SS-N-22)", dmg:330, warhead:"he", range:12.8,
    minRange:2.0, reload:18.0, burst:2, burstDelay:0.9, acc:0.70,
    proj:"missile", speed:345, aoe:1.6, profile:"skim", intercept:0.38,
    tgt:{ground:0,air:0,sea:1,sub:0}, sfx:"missile" },
  /* P-120 Malakhit, 1972 - the Nanuchka's six rounds. 150 km, and the whole
     point of the class was to put that salvo on a 700-tonne hull. */
  ssm_malakhit_p: { name:"P-120 Malakhit (SS-N-9)", dmg:250, warhead:"he", range:11.4,
    minRange:2.0, reload:19.0, burst:1, acc:0.62, proj:"missile", speed:135, aoe:1.5, profile:"skim", intercept:0.85,
    tgt:{ground:0,air:0,sea:1,sub:0}, sfx:"missile" },
  /* Kh-35 Uran, 1996 - a subsonic 145 kg-warhead round in the Harpoon class
     and the first Russian anti-ship missile small enough for a corvette's
     deck. Steregushchiy and the Project 1241.8 Molniya rebuild. */
  ssm_uran_p: { name:"Kh-35 Uran (SS-N-25)", dmg:215, warhead:"he", range:11.8,
    minRange:1.8, reload:14.0, burst:2, burstDelay:0.9, acc:0.70,
    proj:"missile", speed:120, aoe:1.3, profile:"skim", intercept:1.00,
    tgt:{ground:0,air:0,sea:1,sub:0}, sfx:"missile" },

  /* ---- and the one Russian round that really does strike a target ashore ----
     3M-14 Kalibr, in service 2012-2015. Subsonic, terrain-following, 1500 km
     plus, out of the same UKSK cell that holds the 3M-54 anti-ship member of
     the family - which is why the mask is ground AND sea and nothing else.
     It is RECENT and it is CONFINED: a Slava has no UKSK and cannot fire it,
     a Sovremenny has no UKSK and cannot fire it, and Kuznetsov cannot fire
     it. The hulls that can are the small ones - Buyan-M, Karakurt - and the
     two frigate classes, which is the true and slightly embarrassing shape
     of Russian naval land attack: real, demonstrated in anger, and carried
     almost entirely by 950-tonne ships. Slower and more interceptable than
     a Tomahawk (`tlam_n`, range 19.0) and a decade younger. */
  lacm_kalibr_p: { name:"3M-14 Kalibr", dmg:300, warhead:"he", range:18.0,
    minRange:2.5, reload:16.0, burst:1, acc:0.76, proj:"missile", speed:110, aoe:1.5, profile:"cruise", intercept:1.50,
    tgt:{ground:1,air:0,sea:1,sub:0}, sfx:"missile" },
});

/* ---- 1: the six inverted masks ---- */
/* Moskva's air wing hunts submarines. It is the only thing it does. */
setW("w_e60_pact_carrier", { name:"14 x Ka-25PL Hormone-A", warhead:"he",
                             tgt:{ground:0,air:0,sea:0,sub:1} });
addNaval("pact_e60_carrier", "sam_shtorm_p");   /* two twin B-187, 48 rounds */
/* Kuznetsov's twelve under-deck Granit are anti-ship, and her air defence is
   Kinzhal, not the anti-ship missile the mask had her firing at aircraft. */
setW("w_e90_pact_carrier", { name:"12 x P-700 Granit under the deck", warhead:"he",
                             tgt:{ground:0,air:0,sea:1,sub:0} });
setW("w_e00_pact_carrier", { name:"12 x P-700 Granit under the deck", warhead:"he",
                             tgt:{ground:0,air:0,sea:1,sub:0} });
addNaval("pact_e90_carrier", "sam_kinzhal_p");
addNaval("pact_e00_carrier", "sam_kinzhal_p");
/* The corvette template is a GUN - four-round bursts of shells at 700 m/s -
   so it is named for the gun the ship actually mounts, and the ASW mortar it
   was mislabelled as is appended as the separate weapon it is. asw_rbu is
   already correct in rules.js; there is no reason to author a second one. */
setW("w_e50_pact_corvette", { name:"3 x 100mm B-34" });
addNaval("pact_e50_corvette", "asw_rbu");       /* Riga: RBU-2500 and racks */
setW("w_e60_pact_corvette", { name:"2 x twin 57mm AK-725" });
addNaval("pact_e60_corvette", "asw_rbu");
setW("w_e90_pact_corvette", { name:"76mm AK-176 (Grisha V)" });
addNaval("pact_e90_corvette", "asw_rbu");
/* Kashin: two twin 76 mm AK-726 are the gun the template models; the Volna
   is the ship. */
setW("w_e60_pact_destroyer", { name:"2 x twin 76mm AK-726",
                               tgt:{ground:1,air:1,sea:1,sub:0} });
addNaval("pact_e60_destroyer", "sam_volna_p");

/* ---- 2: strip the land attack the Soviet fleet never had ---- */
seaOnly("w_e60_pact_cruiser",     "8 x P-35 in two quad launchers");
seaOnly("w_e60_pact_missileboat", "4 x P-15 Termit SSM");
seaOnly("w_e80_pact_missileboat", "4 x P-15M Termit SSM");
seaOnly("w_e80_pact_destroyer",   "8 x P-270 Moskit SSM");
seaOnly("w_e90_pact_destroyer",   "8 x P-270 Moskit");
seaOnly("w_e80_pact_cruiser",     "16 x P-500 Bazalt in fixed deck tubes");
seaOnly("w_e90_pact_cruiser",     "20 x P-700 Granit");
seaOnly("w_e00_pact_cruiser",     "16 x P-1000 Vulkan in fixed deck tubes");
/* The Nanuchka template is the gun again; the Malakhit salvo is the ship. */
setW("w_e80_pact_corvette", { name:"76mm AK-176 and 30mm AK-630" });
addNaval("pact_e80_corvette", "ssm_malakhit_p");
setW("w_e00_pact_corvette", { name:"100mm A-190 and 30mm AK-630M" });
addNaval("pact_e00_corvette", "ssm_uran_p");
/* Buyan-M keeps ground:1 and is the ONLY generated Soviet/Russian surface
   hull that should have it. Eight UKSK cells, 2014, and the Caspian strike
   on 7 October 2015 is the demonstration. */
setW("w_e00_pact_missileboat", { name:"8 x Kalibr in UKSK cells",
                                 tgt:{ground:1,air:0,sea:1,sub:0} });

/* ---- 3: area air defence, on the hulls that carried it ---- */
addNaval("pact_e60_cruiser",   "sam_volna_p");    /* Kynda: one twin ZIF-101 */
addNaval("pact_e80_destroyer", "sam_uragan_p");   /* Sovremenny: 48 x 9M38 */
addNaval("pact_e90_destroyer", "sam_uragan_p");
addNaval("pact_e80_cruiser",   "sam_fort_p");     /* Slava: 64 rounds */
addNaval("pact_e00_cruiser",   "sam_fort_p");
addNaval("pact_e90_cruiser",   "sam_fort_p");     /* Pyotr Velikiy: 96, Fort-M */
addNaval("pact_e80_carrier",   "sam_shtorm_p");   /* Kiev: two twin B-187, 72 rounds */
addNaval("pact_e80_carrier",   "asw_rbu");
addNaval("pact_e80_corvette",  "ciws_ak630");     /* Nanuchka and after */
